package network.tos.blockchain.ton.contract

import org.ton.boc.BagOfCells
import org.ton.cell.Cell

/** Source-pinned TOS SDK FunC reference family, not an RPC-selected code hash.
 * Source: tosnetwork/tos@bb2b07a40d838940bc16efa6cf72d24bc343c148
 * sdk/js/packages/contracts/src/token/codes.ts. Native Tol family is added separately.
 */
object TokenContractCodes {
    val referenceMaster: Cell by lazy { decode("") }
    val referenceWallet: Cell by lazy { decode("") }
    private fun decode(encoded: String): Cell = BagOfCells(encoded.chunked(2).map { it.toInt(16).toByte() }.toByteArray()).roots.single()
}
